class _DummyRedis:
    def __init__(self):
        self.set_calls = []
        self.get_calls = []
        self.storage = {}

    def setex(self, key, ttl, value):
        self.set_calls.append((key, ttl, value))
        self.storage[key] = value

    def get(self, key):
        self.get_calls.append(key)
        return self.storage.get(key)


